pub fn logs_per_tree(template: &str) -> Option<f64> {
    match template {
        "Birch" => Some(1.0),
        "ChestnutTree" => Some(4.0),
        "Mangrove" => Some(2.0),
        "Maple" => Some(6.0),
        "Oak" => Some(8.0),
        "Pine" => Some(2.0),
        _ => None,
    }
}
/// `DEAD_TREES_KEEP_LOGS[template] === false`.
pub fn dead_tree_loses_logs(template: &str) -> bool {
    let _ = template;
    false
}

