/// sim/model.ts EMITTERS: local tiles, contamination, runs at map start, seep.
pub struct EmitterRule { pub tiles: &'static [(i64, i64)], pub contamination: f64, pub runs: bool, pub seep: bool }
pub fn emitter_rule(template: &str) -> Option<&'static EmitterRule> {
    match template {
        "Aquifer" => Some(&EmitterRule { tiles: &[(1, 1)], contamination: 0.0, runs: false, seep: false }),
        "BadtideDrain" => Some(&EmitterRule { tiles: &[(0, 1)], contamination: 1.0, runs: false, seep: false }),
        "BadwaterSeep" => Some(&EmitterRule { tiles: &[(0, 0), (0, 1), (1, 0), (1, 1)], contamination: 1.0, runs: true, seep: true }),
        "BadwaterSource" => Some(&EmitterRule { tiles: &[(0, 0), (0, 1), (0, 2), (1, 0), (1, 1), (1, 2), (2, 0), (2, 1), (2, 2)], contamination: 1.0, runs: true, seep: false }),
        "WaterSeep" => Some(&EmitterRule { tiles: &[(0, 0), (0, 1), (1, 0), (1, 1)], contamination: 0.0, runs: true, seep: true }),
        "WaterSource" => Some(&EmitterRule { tiles: &[(0, 0)], contamination: 0.0, runs: true, seep: false }),
        _ => None,
    }
}
pub const MAX_STRENGTH_PER_TILE: f64 = 8.0;
pub const GAME_VERSION: &str = "1.1.2.4-52e959e-sw";
pub const GAME_MAX_HEIGHT: f64 = 22.0;
pub const EDITOR_MAX_HEIGHT: f64 = 16.0;
pub const MAX_OBJECT_Z: i64 = 33;
/// features/objects.ts OBJECT_NAMES: a map object's name by its kind.
pub fn object_name(kind: &str) -> Option<&'static str> {
    match kind {
        "mineSite" => Some("Mine site"),
        "relicSmall" => Some("Small relic"),
        "relicMedium" => Some("Medium relic"),
        "relicLarge" => Some("Large relic"),
        "geothermal" => Some("Geothermal field"),
        "thornBelt" => Some("Thorn belt"),
        "weir" => Some("Weir"),
        "plug" => Some("Plug"),
        "bridge" => Some("Natural bridge"),
        "unstableCore" => Some("Unstable core"),
        _ => None,
    }
}
/// analysis/walk.ts WALK_BLOCKERS: the objects a beaver never walks through.
pub fn walk_blocker(template: &str) -> bool {
    matches!(template, "Thorns" | "Blockage" | "NaturalDam" | "UnstableCore" | "GeothermalField" | "UndergroundRuins" | "SmallRelic" | "MediumRelic" | "LargeRelic" | "ReservePile" | "ReserveWarehouse" | "ReserveTank" | "AncientAquiferDrill" | "BadtideDrain")
}
/// features/slopes.ts SLOPE_RULES.bigRegion: a region of this many tiles earns a slope of its own (PLAN §7.5).
pub const BIG_REGION: usize = 400;
/// terrain/clearance.ts PLANT_CLEARANCE: the levels of air a plant needs from its floor up.
pub fn plant_clearance(template: &str) -> Option<i64> {
    match template {
        "Pine" => Some(3),
        "Oak" => Some(3),
        "Birch" => Some(2),
        "Succulent" => Some(2),
        "BlueberryBush" => Some(1),
        _ => None,
    }
}
/// validate/playability.ts EXTRA_BANDS: a map object's distance band from the start (lo, hi, scaled with the map).
pub fn extra_band(kind: &str) -> Option<(f64, f64, bool)> {
    match kind {
        "relicSmall" => Some((13.0, 70.0, true)),
        "relicMedium" => Some((40.0, 140.0, true)),
        "relicLarge" => Some((140.0, f64::INFINITY, true)),
        "geothermal" => Some((30.0, 120.0, true)),
        "mineSite" => Some((30.0, f64::INFINITY, true)),
        "thornBelt" => Some((20.0, f64::INFINITY, false)),
        "unstableCore" => Some((40.0, f64::INFINITY, false)),
        _ => None,
    }
}
/// validate/checks.ts REQUIRED's components, in order of first use: a component's bit in `Entity::comps`.
pub const COMP_NAMES: [&str; 6] = ["WaterSource", "WaterDepthStrengthModifier", "UnstableCore", "FixedStockpile", "RuinModels", "Yielder:Ruin"];
/// validate/checks.ts REQUIRED: the components whose absence crashes the load, as indices into COMP_NAMES.
pub fn required(template: &str) -> &'static [usize] {
    match template {
        "WaterSource" => &[0],
        "BadwaterSource" => &[0],
        "Aquifer" => &[0],
        "BadtideDrain" => &[0],
        "WaterSeep" => &[0, 1],
        "BadwaterSeep" => &[0, 1],
        "UnstableCore" => &[2],
        "ReservePile" => &[3],
        "ReserveTank" => &[3],
        "ReserveWarehouse" => &[3],
        "RuinColumnH1" => &[4, 5],
        "RuinColumnH2" => &[4, 5],
        "RuinColumnH3" => &[4, 5],
        "RuinColumnH4" => &[4, 5],
        "RuinColumnH5" => &[4, 5],
        "RuinColumnH6" => &[4, 5],
        "RuinColumnH7" => &[4, 5],
        "RuinColumnH8" => &[4, 5],
        _ => &[],
    }
}
